import React, { useState, useEffect, useCallback, useRef } from 'react';

// --- Configuration ---
const WS_URL = "ws://localhost:8000/ws";

// --- UI Components ---

const ProgressBar = ({ progress, status, taskId }) => {
    const color = progress === 100 ? 'green' : (status === 'FAILED' ? 'red' : 'blue');

    return (
        <div className="progress-container">
            <div className="progress-header">
                Task ID: {taskId} | Status: {status}
            </div>
            <div className="progress-bar-wrapper">
                <div 
                    className="progress-bar-fill" 
                    style={{ width: `${progress}%`, backgroundColor: color }}
                >
                    {progress.toFixed(1)}%
                </div>
            </div>
        </div>
    );
};


// --- Main Application Component ---

function SearchApp() {
    const [ws, setWs] = useState(null);
    const [isConnected, setIsConnected] = useState(false);

    // Task Management State
    const [currentTaskId, setCurrentTaskId] = useState(null);
    const [taskProgress, setTaskProgress] = useState(0);
    const [taskStatus, setTaskStatus] = useState('IDLE');
    const [taskMessage, setTaskMessage] = useState('Not running.');
    const [searchResults, setSearchResults] = useState([]);

    // User Input State
    const [inputText, setInputText] = useState("A fast red car driving down a wet street.");
    const [threshold, setThreshold] = useState(0.85);
    const [mockVideoPath, setMockVideoPath] = useState("/mock/video1.mp4");
    const [mockEtalonName, setMockEtalonName] = useState("etalon_car_1.jpg");

    // Refs for logging
    const logRef = useRef(null);

    // --- WebSocket Handlers ---

    const logMessage = useCallback((message, type = 'INFO') => {
        const logEntry = document.createElement('div');
        logEntry.className = `log-entry log-${type.toLowerCase()}`;
        logEntry.textContent = `[${new Date().toLocaleTimeString()}] [${type}] ${message}`;

        if (logRef.current) {
            logRef.current.appendChild(logEntry);
            logRef.current.scrollTop = logRef.current.scrollHeight;
        }
    }, []);

    const handleStatusUpdate = useCallback((statusData) => {
        if (!statusData) return;

        setCurrentTaskId(statusData.task_id);
        setTaskProgress(statusData.progress);
        setTaskStatus(statusData.status);
        setTaskMessage(statusData.message);

        if (statusData.progress < 100) {
            logMessage(`Progress: ${statusData.progress.toFixed(1)}% - ${statusData.status}: ${statusData.message}`, 'PROGRESS');
        } else if (statusData.status === 'COMPLETE' || statusData.status === 'FAILED') {
            logMessage(`Task ${statusData.task_id} finished. ${statusData.message}`, statusData.status === 'COMPLETE' ? 'SUCCESS' : 'ERROR');
            if (statusData.result) {
                setSearchResults(statusData.result);
            }
        }
    }, [logMessage]);

    const connectWebSocket = useCallback(() => {
        if (ws) ws.close();

        const newWs = new WebSocket(WS_URL);
        setWs(newWs);

        newWs.onopen = () => {
            setIsConnected(true);
            logMessage(`WebSocket connected to ${WS_URL}`, 'SUCCESS');
        };

        newWs.onmessage = (event) => {
            const data = JSON.parse(event.data);

            if (data.type === "TASK_STARTED") {
                setCurrentTaskId(data.task_id);
                setTaskProgress(0);
                setTaskStatus('PENDING');
                setTaskMessage('Task initialized.');
                logMessage(`New task started: ${data.task_id}`, 'TASK');
            } 

            if (data.type === "STATUS_UPDATE") {
                handleStatusUpdate(data.data);
            }

            if (data.type === "ERROR") {
                logMessage(`API Error: ${data.message}`, 'ERROR');
            }
        };

        newWs.onclose = () => {
            setIsConnected(false);
            setTaskProgress(0);
            setTaskStatus('DISCONNECTED');
            setCurrentTaskId(null);
            logMessage('WebSocket disconnected. Attempting to reconnect...', 'WARNING');
            setTimeout(connectWebSocket, 3000);
        };

        newWs.onerror = (err) => {
            logMessage('WebSocket error occurred.', 'ERROR');
            newWs.close();
        };
    }, [ws, logMessage, handleStatusUpdate]);

    // Effect to handle connection on mount
    useEffect(() => {
        connectWebSocket();
        // Polling mechanism to keep status updated if the broadcaster is slow/unreliable
        const pollInterval = setInterval(() => {
            if (ws && ws.readyState === WebSocket.OPEN && currentTaskId) {
                ws.send(JSON.stringify({ action: "GET_STATUS", payload: { task_id: currentTaskId } }));
            }
        }, 1500);

        return () => {
            if (ws) ws.close();
            clearInterval(pollInterval);
        };
    }, [connectWebSocket, ws, currentTaskId]);

    // --- Action Functions ---

    const handleStartSearch = () => {
        if (!isConnected) {
            logMessage("Cannot start search: WebSocket is not connected.", 'ERROR');
            return;
        }
        if (!currentTaskId) {
            logMessage('Starting new indexing and search job...', 'TASK');
        } else {
            logMessage(`Starting new job, previous task ${currentTaskId} will be overridden.`, 'WARNING');
        }

        setSearchResults([]);

        ws.send(JSON.stringify({
            action: "START_INDEXING",
            payload: {
                video_path: mockVideoPath,
                etalon_filename: mockEtalonName,
                threshold: parseFloat(threshold)
            }
        }));
    };

    // Mock handlers for file uploads (they just update the state variables for the mock backend)
    const handleFileUpload = (type) => {
        logMessage(`Simulating upload for ${type}. (Backend uses hardcoded mock paths)`, 'INFO');
        if (type === 'video') {
            // In a real app, you'd upload the file here and get a path/ID back.
            // setMockVideoPath('/path/to/uploaded/video.mp4');
        }
        if (type === 'etalon') {
            // setMockEtalonName('new_etalon.png');
        }
    };


    // --- Render ---

    const connectionStatusClass = isConnected ? 'status-green' : 'status-red';
    const buttonDisabled = !isConnected || taskStatus === 'INDEXING_FRAMES' || taskStatus === 'SEARCHING';

    return (
        <div className="app-container startup-theme">
            <header className="app-header">
                <span className={`connection-dot ${connectionStatusClass}`}></span>
                <h1 className="title">NEURAL CLIP SEARCH ENGINE</h1>
                <p className="subtitle">Monolithic Indexing & Retrieval System v1.0</p>
            </header>

            <div className="controls-grid">
                <div className="input-group">
                    <h3>Data Inputs</h3>
                    <label>User Query Text:</label>
                    <textarea 
                        value={inputText} 
                        onChange={(e) => setInputText(e.target.value)}
                        placeholder="Enter text query..."
                    />

                    <label>Similarity Threshold:</label>
                    <input 
                        type="number" 
                        step="0.01" 
                        value={threshold}
                        onChange={(e) => setThreshold(e.target.value)}
                        disabled={!isConnected}
                    />

                    <div className="action-buttons">
                        <button 
                            onClick={() => handleFileUpload('video')} 
                            disabled={!isConnected}
                            className="btn-file"
                        >
                            Upload Video (Mock)
                        </button>
                        <button 
                            onClick={() => handleFileUpload('etalon')} 
                            disabled={!isConnected}
                            className="btn-file"
                        >
                            Upload Etalon Image (Mock)
                        </button>
                    </div>
                </div>

                <div className="status-group">
                    <h3>Task Execution</h3>

                    {currentTaskId && (
                        <ProgressBar 
                            progress={taskProgress} 
                            status={taskStatus} 
                            taskId={currentTaskId}
                        />
                    )}
                    {!currentTaskId && (
                        <p className="status-message">System Idle.</p>
                    )}

                    <div className="main-action">
                        <button 
                            onClick={handleStartSearch} 
                            disabled={buttonDisabled}
                            className="btn-search"
                        >
                            {currentTaskId && taskProgress < 100 ? 'RESTART SEARCH' : 'START INDEX & SEARCH'}
                        </button>
                        <p className="status-detail">{taskMessage}</p>
                    </div>

                    <div className="mock-info">
                        <p>Mock Video Path: <code>{mockVideoPath}</code></p>
                        <p>Mock Etalon Name: <code>{mockEtalonName}</code></p>
                    </div>
                </div>
            </div>

            <div className="results-panel">
                <h3>Search Results ({searchResults.length} Matches)</h3>
                <div className="results-list">
                    {searchResults.length > 0 ? (
                        searchResults.map((res, index) => (
                            <div key={index} className="result-item">
                                <span className="res-score">{(res.similarity_score * 100).toFixed(2)}%</span> | 
                                Video: <code>{res.video_id}</code> | 
                                Frame: <code>{res.frame_index}</code>
                            </div>
                        ))
                    ) : (
                        <p className="status-message">Results will appear here upon completion.</p>
                    )}
                </div>
            </div>

            <div className="log-window">
                <h4>System Log</h4>
                <div ref={logRef} id="statusLog">
                    {/* Log entries will be dynamically added here */}
                </div>
